Time Complexity: O(n2)Auxiliary Space: O(1)Efficient Approach: we use the two-pointer technique (sliding window), but adapt it to handle products. Here is a way to approach it:Initialize two pointers, start and end.Use a variable product to keep track of the product of elements in the current window.Expand the window by moving end to the right and update the product.If the product exceeds k, move start to the right until the product is less than or equal to k.Check if the product matches k.Below is the implementation of above idea. 
            C++

    #include <iostream>
using namespace std;

// Function to check if there exists a subarray with a product equal to k
bool hasSubarrayWithProduct(int* arr, int n, int k) {
    int start = 0;
    int product = 1;

    // Special case when k is zero
    if (k == 0) {
        for (int i = 0; i < n; i++) {
            if (arr[i] == 0) return true;
        }
        return false;
    }

    for (int end = 0; end < n; end++) {

        // Reset window when zero is encountered
        if (arr[end] == 0) {
            start = end + 1;
            product = 1;
            continue;
        }

        product *= arr[end];

        // Shrink window if product exceeds k
        while (start <= end && product > k) {
            product /= arr[start];
            start++;
        }

        // Check if current window product equals k
        if (product == k) {
            return true;
        }
    }

    return false;
}

int main() {
    int arr[] = {1, 2, 3, 4};
    int k = 6;
    int n = sizeof(arr) / sizeof(arr[0]);

    if (hasSubarrayWithProduct(arr, n, k)) {
        cout << "YES\n";
    } else {
        cout << "NO\n";
    }

    return 0;
}


